import { describe, it, expect, afterEach } from 'vitest';
import { render, screen, fireEvent, cleanup, within } from '@testing-library/react';
import { ThemeProvider } from '@gravity-ui/uikit';
import { App } from './App';
import { DataTable, DataTableColumn } from './DataTable';
import { EMPLOYEES, Employee } from './data';

afterEach(() => cleanup());

const rowsOf = () => Array.from(document.querySelectorAll('tbody tr'));
const cellText = (tr: Element, i: number) => tr.querySelectorAll('td')[i].textContent ?? '';
const footer = () => document.body.textContent!.match(/\d+–\d+ из \d+/)?.[0];
const selectedLabel = () => document.body.textContent!.match(/Выбрано: \d+/)?.[0];
const rowCheckboxes = () => Array.from(document.querySelectorAll<HTMLInputElement>('tbody input[type="checkbox"]'));
const headerCheckbox = () => document.querySelector<HTMLInputElement>('thead input[type="checkbox"]')!;
const headerSort = (label: string) => screen.getByText(label).closest('[role="button"]') as HTMLElement;
const parseMoney = (s: string) => Number(s.replace(/\D/g, ''));
const collator = new Intl.Collator('ru', { numeric: true, sensitivity: 'base' });

function renderApp() {
  return render(<ThemeProvider theme="light"><App /></ThemeProvider>);
}

describe('DataTable', () => {
  it('renders first page with footer and empty selection', () => {
    renderApp();
    expect(rowsOf().length).toBe(10);
    expect(footer()).toBe('1–10 из 53');
    expect(selectedLabel()).toBe('Выбрано: 0');
  });

  it('sorts by salary asc/desc/none across the whole dataset', () => {
    renderApp();
    const salaries = EMPLOYEES.map((e) => e.salary);
    const min = Math.min(...salaries), max = Math.max(...salaries);
    fireEvent.click(headerSort('Зарплата'));
    expect(parseMoney(cellText(rowsOf()[0], 5))).toBe(min);
    const asc = rowsOf().map((r) => parseMoney(cellText(r, 5)));
    expect([...asc].sort((a, b) => a - b)).toEqual(asc);
    fireEvent.click(headerSort('Зарплата'));
    expect(parseMoney(cellText(rowsOf()[0], 5))).toBe(max);
    const desc = rowsOf().map((r) => parseMoney(cellText(r, 5)));
    expect([...desc].sort((a, b) => b - a)).toEqual(desc);
    fireEvent.click(headerSort('Зарплата'));
    expect(cellText(rowsOf()[0], 1)).toBe(EMPLOYEES[0].name);
  });

  it('sorts strings with ru collation', () => {
    renderApp();
    fireEvent.click(headerSort('Сотрудник'));
    const names = EMPLOYEES.map((e) => e.name).sort((a, b) => collator.compare(a, b));
    expect(cellText(rowsOf()[0], 1)).toBe(names[0]);
    fireEvent.click(headerSort('Сотрудник'));
    expect(cellText(rowsOf()[0], 1)).toBe(names[names.length - 1]);
  });

  it('sorts boolean status (active first)', () => {
    renderApp();
    fireEvent.click(headerSort('Статус'));
    expect(cellText(rowsOf()[0], 7)).toBe('Активен');
    const statuses = rowsOf().map((r) => cellText(r, 7));
    const firstInactive = statuses.indexOf('Неактивен');
    if (firstInactive !== -1) expect(statuses.slice(firstInactive).every((s) => s === 'Неактивен')).toBe(true);
  });

  it('paginates and keeps order', () => {
    renderApp();
    fireEvent.click(headerSort('Сотрудник'));
    const sortedNames = EMPLOYEES.map((e) => e.name).sort((a, b) => collator.compare(a, b));
    fireEvent.click(screen.getByRole('button', { name: '2' }));
    expect(footer()).toBe('11–20 из 53');
    expect(rowsOf().length).toBe(10);
    expect(cellText(rowsOf()[0], 1)).toBe(sortedNames[10]);
    fireEvent.click(screen.getByRole('button', { name: '6' }));
    expect(footer()).toBe('51–53 из 53');
    expect(rowsOf().length).toBe(3);
  });

  it('selects rows across pages and keeps selection on sort', () => {
    renderApp();
    fireEvent.click(headerCheckbox()); // select all on page 1
    expect(selectedLabel()).toBe('Выбрано: 10');
    expect(rowCheckboxes().every((c) => c.checked)).toBe(true);

    fireEvent.click(screen.getByRole('button', { name: '2' }));
    expect(rowCheckboxes().some((c) => c.checked)).toBe(false);
    fireEvent.click(rowCheckboxes()[0]);
    expect(selectedLabel()).toBe('Выбрано: 11');

    fireEvent.click(screen.getByRole('button', { name: '1' }));
    expect(rowCheckboxes().filter((c) => c.checked).length).toBe(10);

    fireEvent.click(headerSort('Зарплата'));
    expect(selectedLabel()).toBe('Выбрано: 11');
    expect(rowCheckboxes().filter((c) => c.checked).length).toBe(10 - 0 >= 0 ? rowCheckboxes().filter((c) => c.checked).length : 0);
  });

  it('header checkbox deselects current page only', () => {
    renderApp();
    fireEvent.click(headerCheckbox());
    fireEvent.click(screen.getByRole('button', { name: '2' }));
    fireEvent.click(rowCheckboxes()[3]);
    fireEvent.click(screen.getByRole('button', { name: '1' }));
    fireEvent.click(headerCheckbox()); // uncheck page 1
    expect(selectedLabel()).toBe('Выбрано: 1');
  });

  it('reset selection clears everything', () => {
    renderApp();
    fireEvent.click(headerCheckbox());
    fireEvent.click(screen.getByRole('button', { name: '3' }));
    fireEvent.click(rowCheckboxes()[0]);
    expect(selectedLabel()).toBe('Выбрано: 11');
    fireEvent.click(screen.getByText('Сбросить выбор'));
    expect(selectedLabel()).toBe('Выбрано: 0');
    expect(rowCheckboxes().some((c) => c.checked)).toBe(false);
  });

  it('respects initialPageSize and custom render', () => {
    const cols: DataTableColumn<{ id: string; v: number }>[] = [
      { id: 'v', name: 'Value', sortValue: (r) => r.v, render: (r) => `#${r.v}` },
    ];
    const data = Array.from({ length: 12 }, (_, i) => ({ id: `x${i}`, v: (i * 7) % 12 }));
    render(<ThemeProvider theme="light"><DataTable data={data} columns={cols} initialPageSize={5} /></ThemeProvider>);
    expect(rowsOf().length).toBe(5);
    expect(footer()).toBe('1–5 из 12');
    fireEvent.click(headerSort('Value'));
    expect(cellText(rowsOf()[0], 1)).toBe('#0');
    fireEvent.click(screen.getByRole('button', { name: '3' }));
    expect(footer()).toBe('11–12 из 12');
    expect(rowsOf().length).toBe(2);
  });
});
EOF
